			/* updateMasterMpRqQuotationRemarkPop */
			UPDATE KEP_RQDT_NOTE_MNG
			SET ADD_NOTE = #{ADD_NOTE}
			,CHANGE_USER_ID = #{USER_ID}
 			,CHANGE_DATE = SYSDATE
 			,IMAGE_KEY = #{IMAGE_KEY}
			WHERE BUYER = #{BUYER}
			AND QUOTATION_NO = #{QUOTATION_NO}
			AND QUOTATION_SEQ = #{QUOTATION_SEQ}
			AND REVISION = #{REVISION}
			AND SEQ = #{SEQ}


			/* delMasterMpRqQuotationRemarkPop */
			UPDATE KEP_RQDT_NOTE_MNG
			SET STATUS = 'D'
			,CHANGE_USER_ID = #{USER_ID}
 			,CHANGE_DATE = SYSDATE
			WHERE BUYER = #{BUYER}
			AND QUOTATION_NO = #{QUOTATION_NO}
			AND QUOTATION_SEQ = #{QUOTATION_SEQ}
			AND REVISION = #{REVISION}
			AND SEQ = #{SEQ}
